const task = $('Validate research task').first().json;
const agent = $input.first().json;
if (typeof agent.output !== 'string' || !agent.output.trim()) throw new Error('The Agent did not return a brief. Inspect its execution before retrying paid calls.');
if (!Array.isArray(agent.intermediateSteps)) throw new Error('Enable Return Intermediate Steps on the Research agent to preserve search evidence.');
const searches = agent.intermediateSteps.map((step, index) => {
  let observation = step.observation;
  if (typeof observation === 'string') {
    try { observation = JSON.parse(observation); }
    catch { throw new Error('Could not decode tool evidence for search ' + (index + 1) + '. Inspect the Agent execution.'); }
  }
  const values = Array.isArray(observation) ? observation.flat(Infinity) : [observation];
  const envelopes = values.map(value => value?.json ?? value);
  if (!envelopes.length || envelopes.some(value => !value || typeof value !== 'object')) throw new Error('Missing tool evidence.');
  const completed = envelopes.every(value => value.status === 'done' && Array.isArray(value.results?.[0]?.organic));
  const results = completed ? envelopes.flatMap(value => value.results[0].organic) : [];
  return {
    query: step.action?.toolInput?.query ?? null,
    status: completed ? (results.length ? 'results_returned' : 'no_results') : 'tool_error_or_incomplete_response',
    returned_count: completed ? results.length : null,
    credits: completed && envelopes.every(value => typeof value.usage?.credits === 'number') ? envelopes.reduce((sum, value) => sum + value.usage.credits, 0) : null,
    responses: envelopes,
  };
});
const totalCredits = searches.length && searches.every(search => search.credits !== null)
  ? searches.reduce((sum, search) => sum + search.credits, 0) : null;
const evidence = {
  question: task.question, context: task.context, preferred_sources: task.preferred_sources,
  country: task.country, search_language: task.search_language, requested_results_per_search: task.results_per_search,
  evidence_status: searches.length ? 'searches_recorded' : 'no_searches_recorded',
  tool_calls: searches.length, flashdata_credits: totalCredits,
  limitations: 'Search snippets only. Collection timestamps are not publication dates. Citations and conclusions require human review. Model charges are separate and not included in flashdata_credits.',
  searches,
};
const log = searches.length ? searches.map((search, i) =>
  '- Search ' + (i + 1) + ': ' + JSON.stringify(search.query) + ' — ' + search.status + '; results: ' + (search.returned_count ?? 'unknown') + '; Credits: ' + (search.credits ?? 'unknown')
).join('\n') : 'No tool searches were recorded. This brief has no recorded web evidence; do not treat it as verified research.';
return [{ json: {
  content: agent.output.trim() + '\n\n---\n## Search execution record\n' + log + '\n\nSearch snippets are not full-page evidence. Review the original links and the companion JSON before implementation. Model charges are separate.\n',
  ...evidence,
} }];
